pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 delay) public {
        delay = bound(delay, 0, 1000000);
        vm.assume(delay >= c.getMinDelay());
        // First, we need a proposer role to schedule and cancel.
        // But the test itself is the deployer and has TIMELOCK_ADMIN_ROLE, not PROPOSER_ROLE.
        // We grant PROPOSER_ROLE to this contract for scheduling.
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        // Also grant EXECUTOR_ROLE to address(0) to allow execution without role check
        c.grantRole(c.EXECUTOR_ROLE(), address(0));
        // Schedule a dummy operation
        // We need a target that won't revert when called. Use address(0) with no value/data.
        address target = address(0);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 opId = c.hashOperation(target, value, data, predecessor, salt);
        // Before cancel, operation should be pending
        bool wasPending = c.isOperationPending(opId);
        // Cancel the operation
        c.cancel(opId);
        // After cancel, operation should NOT be pending
        bool isPendingAfterCancel = c.isOperationPending(opId);
        // The general rule: a pending operation becomes not pending after cancel
        assertTrue(wasPending && !isPendingAfterCancel);
    }
}

