pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(address account, bytes32 role, uint256 dummy) public {
        vm.assume(account != address(0) && account != address(this));
        vm.assume(dummy < 1000);

        // Get initial hasRole value
        bool initialHasRole = c.hasRole(role, account);

        // Grant the role to account via the public interface (requires admin role)
        // We are the admin (address(this) has DEFAULT_ADMIN_ROLE)
        vm.prank(address(this));
        c.grantRole(role, account);

        // After granting, hasRole must be true
        bool afterGrant = c.hasRole(role, account);

        // Now cancel an arbitrary operation (we need a valid id, but any id works as long as not pending)
        bytes32 operationId = keccak256(abi.encode(account, dummy));

        // We can call cancel with any id; if it reverts (not pending), that's fine
        (bool cancelSuccess, ) = address(c).call(abi.encodeWithSelector(c.cancel.selector, operationId));

        // After cancel, role membership for account must still be true (unchanged)
        bool afterCancel = c.hasRole(role, account);

        // The rule: after granting, hasRole returns true, and cancel does not alter role membership
        assertTrue(afterGrant && afterCancel);
    }
}

