import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(uint256 id) public {
        // Bound id to avoid excessive gas
        vm.assume(id != 0);
        // Only test if operation is not already pending (avoid revert from cancel)
        vm.assume(!c.isOperationPending(bytes32(id)));

        // Try to cancel a non-pending operation - in reference this reverts, in mutant it may succeed
        // We check if cancel reverts
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", bytes32(id)));

        // General rule: If cancel succeeds, the operation must become done (isOperationDone returns true)
        // In reference: cancel never succeeds on non-pending operations, so this is vacuously true
        // In mutant: cancel may succeed because isOperationPending incorrectly returns true
        if (success) {
            assertTrue(c.isOperationDone(bytes32(id)), "After successful cancel, operation should be done");
        }
    }
}

