pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, bool cancelFirst) public {
        // Ensure the operation is not already pending (simulate no schedule unless we schedule)
        vm.assume(!c.isOperationPending(id));

        // If cancelFirst is true, try to cancel (should revert because not pending)
        if (cancelFirst) {
            vm.expectRevert("TimelockController: operation cannot be cancelled");
            c.cancel(id);
        } else {
            // Schedule the operation first to make it pending
            // Use a dummy delay sufficient to pass
            uint256 delay = c.getMinDelay();
            vm.assume(delay >= 0);
            // Actually schedule with a dummy call
            // We need to be proposer
            vm.prank(address(this));
            c.schedule(address(this), 0, "", bytes32(0), id, delay);
            // Now cancel should succeed
            bool wasPending = c.isOperationPending(id);
            c.cancel(id);
            // After cancel, isOperation should return 0 (i.e., getTimestamp(id) == 0)
            bool isOpAfter = c.isOperation(id);
            // The rule: after a successful cancel, isOperation returns false
            assertTrue(!isOpAfter);
        }
    }
}

