pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 delay) public {
        vm.assume(delay >= 0 && delay <= 1000); // bound delay to reasonable range
        // Schedule an operation so that the timestamp is set
        bytes32 salt = keccak256(abi.encode(id, delay));
        c.schedule(address(this), 0, "", bytes32(0), salt, delay);
        bytes32 operationId = c.hashOperation(address(this), 0, "", bytes32(0), salt);

        // The operation is pending if its timestamp > 1
        uint256 timestamp = c.getTimestamp(operationId);
        bool expectedPending = timestamp > 1;
        bool actualPending = c.isOperationPending(operationId);

        // Cancel the operation to trigger the _afterCall timestamp setting
        c.cancel(operationId);

        // After cancel, operation is not pending (timestamp = 1 means done)
        bool afterCancelPending = c.isOperationPending(operationId);

        // The rule: before cancel, isOperationPending matches (timestamp > 1); after cancel, it is false
        assertTrue(actualPending == expectedPending && !afterCancelPending);
    }
}

