pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 timestamp) public {
        // Ensure timestamp is either 0 (no operation) or >= 1
        timestamp = bound(timestamp, 0, 1000);
        vm.assume(timestamp == 0 || timestamp >= 1);
        // Set the timestamp directly via the internal mapping (not accessible), so we simulate by scheduling
        // Instead, we use the schedule function to set a known operation ID
        // We need to create a deterministic operation ID from fuzz params
        // Use dummy values for target, value, data, predecessor, salt
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = abi.encode(id);
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(timestamp));
        // Schedule operation with delay = 0 (minDelay is 0 in setUp)
        c.schedule(target, value, data, predecessor, salt, 0);
        bytes32 operationId = c.hashOperation(target, value, data, predecessor, salt);
        // Now operation is pending with timestamp = block.timestamp (which is > 1)
        // Cancel it to test the isOperationPending condition difference
        // But we need to ensure cancel works: isOperationPending should return true before cancel
        // For the buggy version, if timestamp == 1, isOperationPending would also return true (incorrectly)
        // Since we scheduled with delay 0, timestamp = block.timestamp > 1, so both versions return true
        // To trigger the difference, we need an operation with timestamp exactly 1
        // We cannot set timestamp to 1 directly, but we can simulate by canceling and then checking
        // However, cancel deletes the timestamp (sets to 0), not to 1
        // The only way timestamp becomes 1 is via _afterCall, which requires TIMELOCK_ADMIN_ROLE
        // So we prank as the contract itself to call _afterCall indirectly via execute
        // Execute the operation (requires EXECUTOR_ROLE, which address(this) has)
        c.execute(target, value, data, predecessor, salt);
        // After execute, timestamp should be _DONE_TIMESTAMP = 1
        // Now test isOperationPending
        // For P (reference): isOperationPending returns getTimestamp(id) > 1, which is false for timestamp == 1
        // For M (buggy): isOperationPending returns getTimestamp(id) >= 1, which is true for timestamp == 1
        // But we cannot directly call cancel because isOperationPending returns false for P (so cancel fails)
        // We need a different approach: schedule another operation, then execute it to set timestamp to 1
        // Actually, after execute, timestamp is set to 1, so we can test cancel on that same id
        // Wait: cancel requires isOperationPending(id) to be true, which for P is false (1 > 1 is false)
        // For M it would be true (1 >= 1 true). So cancel will revert in P but succeed in M
        // We can test this by wrapping cancel in try/catch
        // But the requirement says the test should drive through cancel and assert a general rule
        // The rule: if getTimestamp(id) == 1, then isOperationPending(id) should be false for P and true for M
        // We can check this by observing either revert or success of cancel
        // Let's try:
        bool reverted;
        try c.cancel(operationId) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // For P: cancel should revert because isOperationPending returns false (timestamp == 1 > 1 is false)
        // For M: cancel should succeed because isOperationPending returns true (timestamp == 1 >= 1 is true)
        // So the rule for P is: when timestamp == 1, cancel reverts
        assertTrue(reverted, "cancel should revert when timestamp == 1");
    }
}

