pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        vm.assume(delay >= c.getMinDelay());
        vm.assume(target != address(0));

        // Schedule an operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Warp to make the operation ready (timestamp == block.timestamp)
        vm.warp(block.timestamp + delay);

        // Now the operation's timestamp should be exactly _DONE_TIMESTAMP (1) if we execute
        // But for this test, we just try to cancel. Cancel should succeed only if the operation is pending.
        // In the reference version, isOperationPending returns true when timestamp > _DONE_TIMESTAMP (1).
        // At this point timestamp = block.timestamp (which is > 1), so cancel should work.
        // But we want to test the edge case where timestamp == _DONE_TIMESTAMP.
        // We can achieve this by executing the operation first, then timestamps[id] becomes _DONE_TIMESTAMP.

        // Execute the operation to set its timestamp to _DONE_TIMESTAMP
        c.execute(target, value, data, predecessor, salt);

        // Now the operation is done (timestamp == _DONE_TIMESTAMP).
        // In the reference code, isOperationPending returns false because timestamp > _DONE_TIMESTAMP is false.
        // So cancel should revert with "TimelockController: operation cannot be cancelled".
        // In the mutant, isOperationPending returns true because timestamp >= _DONE_TIMESTAMP.
        // So cancel would succeed, which is incorrect (canceling an already done operation).

        // Attempt to cancel
        try c.cancel(id) {
            // If it succeeds, we must check that the operation is now pending? No, cancel should fail.
            revert("cancel should not succeed");
        } catch {
            // Expected revert - cancel should fail because operation is not pending
        }

        // Assert that after the cancel attempt, the operation is still done (timestamp == _DONE_TIMESTAMP)
        assertTrue(c.isOperationDone(id));
    }
}

