pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 delay) public {
        vm.assume(delay > 0);
        vm.deal(address(this), 0);
        bytes32 salt = bytes32(uint256(1));
        bytes memory data = "";
        bytes32 opId = c.hashOperation(address(0), 0, data, bytes32(0), salt);
        // give proposer role to this contract to schedule
        // deployer already has admin role, grant proposer to self
        // skip since constructor already granted TIMELOCK_ADMIN_ROLE to msg.sender
        // but proposer role is not granted to this contract; we need to grant it via the admin role
        // We'll use the admin role to grant proposer role to this contract
        // But the admin role is held by this contract (address(this)) because setUp runs as msg.sender
        // Actually constructor granted TIMELOCK_ADMIN_ROLE to _msgSender() (which is address(this) during setUp)
        // So address(this) can grant PROPOSER_ROLE to itself
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        // schedule the operation
        c.schedule(address(0), 0, data, bytes32(0), salt, delay);
        // advance time
        vm.warp(block.timestamp + delay);
        // execute the operation (need executor role)
        c.grantRole(c.EXECUTOR_ROLE(), address(this));
        c.execute(address(0), 0, data, bytes32(0), salt);
        // now cancel an operation that is pending (should be impossible after execute)
        // Cancel a different operation to test the property
        // Create a second operation that is pending
        bytes32 id2 = c.hashOperation(address(0), 0, data, bytes32(0), bytes32(uint256(2)));
        c.schedule(address(0), 0, data, bytes32(0), bytes32(uint256(2)), delay);
        vm.warp(block.timestamp + delay);
        // cancel it
        bool cancelled = false;
        try c.cancel(id2) {
            cancelled = true;
        } catch {
            // do nothing
        }
        if (cancelled) {
            assertTrue(!c.isOperationPending(id2));
        }
    }
}

