    function testFuzz_property(bytes32 id, uint256 delay, uint256 timeJump) public {
        // Bound delay to reasonable values and ensure it's >= minDelay (0)
        delay = bound(delay, 0, 1000000);
        // Bound timeJump to ensure we can make the operation ready
        timeJump = bound(timeJump, delay, delay + 1000000);

        // Create a dummy operation (we need to schedule it first)
        vm.assume(keccak256(abi.encode(id)) != 0); // Ensure id is not zero

        // Schedule the operation
        bytes32 operationId = id;
        // We need to schedule using a proposer role
        // The contract already has DEFAULT_ADMIN_ROLE
        // We'll schedule a simple operation

        // First, grant PROPOSER_ROLE to this contract
        // But set up already has address(this) as admin, so we can grant
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        // Schedule with target = address(0), value = 0, empty data, no predecessor, salt = bytes32(0)
        // Use delay that satisfies >= minDelay
        vm.expectRevert(); // It might revert if operation already exists, but we use unique id
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), delay);

        // Now check if operation is pending
        bool pending = c.isOperationPending(operationId);

        // If pending, then cancel should succeed and after cancel it should not be pending
        if (pending) {
            c.cancel(operationId);
            assertTrue(!c.isOperationPending(operationId));
        }
    }
}

