                assertTrue(pendingAfter == false, "after cancel, operation should not be pending");
            } catch {
                // If cancel reverts, the operation must not be pending (contradiction to test setup)
                assertTrue(false, "cancel should not revert for pendable operation");
            }
        } catch {
